db.getCollection("payments").drop();
db.createCollection("payments", {
  validator: { $jsonSchema: {
      bsonType: "object",
      required: ["payment_id", "member_id", "amount", "status", "due_date"],
      properties: {
        member_id: { bsonType: "objectId" },
        amount: { bsonType: ["int", "long", "double"], minimum: 0 },
        currency: { enum: ["INR"] },
        payment_mode: { enum: ["cash", "card", "UPI", null] },
        status: { enum: ["paid", "pending", "overdue"] },
        due_date: { bsonType: "date" }
      }
    } },
  validationLevel: "strict",
  validationAction: "error"
});

db.members.createIndex({ email: 1 }, { unique: true, name: "uq_email" });
db.members.createIndex({ member_id: 1 }, { unique: true, name: "uq_member_id" });
db.members.createIndex({ assigned_trainer_id: 1 }, { name: "ix_trainer" });
db.members.createIndex({ "membership.type": 1, "membership.status": 1 }, { name: "ix_tier_status" });
db.members.createIndex({ referred_by: 1 }, { name: "ix_referred_by" });
db.trainers.createIndex({ email: 1 }, { unique: true, name: "uq_email" });
db.trainers.createIndex({ trainer_id: 1 }, { unique: true, name: "uq_trainer_id" });
db.workout_plans.createIndex({ member_id: 1, status: 1 }, { name: "ix_member_status" });
db.workout_plans.createIndex({ trainer_id: 1 }, { name: "ix_trainer" });
db.classes.createIndex({ trainer_id: 1 }, { name: "ix_trainer" });
db.classes.createIndex({ "enrolled_members.member_id": 1 }, { name: "ix_enrolled_member" });
db.classes.createIndex({ class_name: "text", category: "text" }, { name: "tx_class_search" });
db.class_sessions.createIndex({ class_id: 1, date: 1 }, { name: "ix_class_date" });
db.attendance.createIndex({ member_id: 1, date: -1 }, { name: "ix_member_date" });
db.attendance.createIndex({ session_id: 1, member_id: 1 }, { unique: true, name: "uq_session_member" });
db.attendance.createIndex({ class_id: 1, status: 1 }, { name: "ix_class_status" });
db.payments.createIndex({ member_id: 1, status: 1 }, { name: "ix_member_status" });
db.payments.createIndex({ due_date: 1 }, { name: "ix_due_date" });
db.payments.createIndex({ status: 1, due_date: 1 }, {
  name: "px_unpaid_dues",
  partialFilterExpression: { status: { "$in": ["pending", "overdue"] } }
});

// Read-only view used by the member dashboard (hides password_hash).
db.getCollection("member_dashboard").drop();
db.createView("member_dashboard", "members", [
  {
    "$lookup": { from: "trainers", localField: "assigned_trainer_id", foreignField: "_id", as: "t" }
  },
  { "$lookup": { from: "payments", localField: "_id", foreignField: "member_id", as: "p" } },
  {
    "$project": {
      _id: 0,
      member_id: 1,
      name: 1,
      tier: "$membership.type",
      status: "$membership.status",
      trainer: { "$first": "$t.name" },
      unpaid_amount: {
        "$sum": {
          "$map": {
            input: { "$filter": { input: "$p", as: "x", cond: { "$ne": ["$$x.status", "paid"] } } },
            as: "u",
            in: "$$u.amount"
          }
        }
      }
    }
  }
]);

print("gym_db created: " + db.getCollectionNames().sort().join(", "));
